 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The repeated 2s form parallel rails. The lines run perpendicular to
    # the 3x3 markers' rays.
    row_counts = [sum(v == 2 for v in row) for row in grid]
    col_counts = [sum(grid[r][c] == 2 for r in range(h)) for c in range(w)]
    row_rails = [r for r, n in enumerate(row_counts) if n >= max(4, int(w * 0.55))]
    col_rails = [c for c, n in enumerate(col_counts) if n >= max(4, int(h * 0.55))]
    horizontal_rails = len(row_rails) >= len(col_rails) and bool(row_rails)
    rails = row_rails if horizontal_rails else col_rails

    out = [row[:] for row in grid]
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    # Rays follow the direction perpendicular to the rails; at every rail
    # crossing, add the 3x3 halo around its 2 marker.
    for r, c in centers:
        if horizontal_rails:
            ray = [(rr, c) for rr in range(h)]
            crossings = [(rr, c) for rr in rails]
        else:
            ray = [(r, cc) for cc in range(w)]
            crossings = [(r, cc) for cc in rails]
        for rr, cc in ray:
            if out[rr][cc] == 0:
                out[rr][cc] = 1
        for rr, cc in crossings:
            if grid[rr][cc] != 2:
                continue
            for ar in range(max(0, rr - 1), min(h, rr + 2)):
                for ac in range(max(0, cc - 1), min(w, cc + 2)):
                    if (ar, ac) != (rr, cc) and out[ar][ac] in (0, 2):
                        out[ar][ac] = 1
    return out
